import http from "k6/http";
import { check, fail, sleep } from "k6";

// Generated by Ballast from a scenario graph. Editing this does nothing: the
// graph is what is stored, and this file is written from it again every time.
//
// No options block: Ballast writes the load from the run's profile, and k6
// reads it from the module it runs instead of this one.

const BASE_URL = __ENV.BASE_URL;

export default function () {
  const vars = {};
  let res = null;
  res = http.request("GET", BASE_URL + "/items", null, {
    headers: {},
    tags: { name: "GET /items" },
  });
  vars["items"] = null;
  try {
    vars["items"] = res.json("ids");
  } catch (error) {
    vars["items"] = null;
  }
  if (vars["items"] === null || vars["items"] === undefined || vars["items"] === "") {
    fail("could not extract the variable \"items\" from the response body (ids)");
  }
  const list_each = vars["items"];
  if (!Array.isArray(list_each)) {
    fail("the variable \"items\" is not a list, so the loop cannot walk it");
  }
  for (let i = 0; i < Math.min(list_each.length, 20); i++) {
    vars["item"] = list_each[i];
    res = http.request("GET", BASE_URL + "/items/" + encodeURIComponent(vars["item"]), null, {
      headers: {},
      tags: { name: "GET /items/{item}" },
    });
  }
  return;
}
